import Router from "../router.js";
import User from "../user.js";
import { getCurrentVersion } from "../utils/env.js";
import { asset, getPath, normalizePath } from "../utils/path.js";
import { acceptsLanguages, fromFileUrl } from "../../deps/std.js";
import { filter, render } from "../../deps/vento.js";
// @ts-expect-error no types for locale.js
import { setLocale, t } from "../../static/common/locale.js";
import documentRoute from "./document.js";
import collectionRoute from "./collection.js";
import versionsRoute from "./versions.js";
import indexRoute from "./index.js";
import uploadsRoute from "./uploads.js";
import actionsRoute from "./actions.js";
export default function init(options) {
    filter("path", (args) => getPath(options.basePath, ...args));
    filter("asset", (url) => asset(options.basePath, url));
    const app = new Router({
        cms: options.content,
        sourcePath: options.sourcePath,
    }, options.basePath);
    app
        .path("/auth/*", ({ next }) => {
        const { authMethod } = options;
        if (!authMethod) {
            return new Response("Not found", { status: 404 });
        }
        return next()
            .post("/logout", ({ request }) => authMethod.logout(request))
            .default(({ request }) => authMethod.fetch(request));
    })
        .path("/*", async ({ request, next }) => {
        let user;
        // Authentication
        if (options.authMethod && options.users.size) {
            const result = await options.authMethod.login(request);
            if (result instanceof Response) {
                return result;
            }
            else {
                const config = options.users.get(result);
                if (!config) {
                    throw new Error("AuthProvider resolved with an invalid user.");
                }
                user = new User(result, config);
            }
        }
        else {
            user = new User(); // anonymous user
        }
        // Detect the language
        const langs = ["en", "gl", "es", "pt"];
        const lang = user.language ?? acceptsLanguages(request, ...langs) ?? langs[0];
        await setLocale(lang);
        // Template renderer
        const renderTemplate = (file, data) => render(file, {
            ...data,
            t,
            lang,
            jsImports: options.jsImports,
            extraHead: options.extraHead,
            cmsVersion: getCurrentVersion(),
            git: options.content.git,
            actions: options.content.actions,
        });
        return next({ user, lang, render: renderTemplate })
            .path("/", indexRoute)
            .path("/document/*", documentRoute)
            .path("/collection/*", collectionRoute)
            .path("/uploads/*", uploadsRoute)
            .path("/versions/*", versionsRoute)
            .path("/actions/*", actionsRoute)
            .get("/manifest.json", () => {
            return {
                name: "LumeCMS",
                short_name: "LumeCMS",
                description: "CMS to edit the content of your static site",
                start_url: getPath(options.basePath),
                display: "browser",
                display_override: ["standalone", "minimal-ui"],
                icons: [
                    {
                        sizes: "192x192",
                        src: asset(options.basePath, "/pwa-icon-192.png"),
                        type: "image/png",
                    },
                    {
                        sizes: "512x512",
                        src: asset(options.basePath, "/pwa-icon-512.png"),
                        type: "image/png",
                    },
                ],
            };
        })
            .catch(async (params) => {
            const content = await renderTemplate("error.vto", {
                t,
                user,
                error: params.error?.stack,
            });
            return new Response(content, {
                status: 500,
                headers: {
                    "Content-Type": "text/html; charset=utf-8",
                },
            });
        });
    });
    // Serve static files from local directory
    app.staticFiles("/*", fromFileUrl(import.meta.resolve("../../static")));
    const { staticFolders } = options;
    if (staticFolders) {
        for (const [prefix, path] of Object.entries(staticFolders)) {
            const folder = normalizePath(prefix, "*");
            if (path.startsWith("file:")) {
                app.staticFiles(folder, fromFileUrl(path));
            }
            else {
                app.staticFiles(folder, path);
            }
        }
    }
    return app;
}
